{
  "decision": "review",
  "icd10_code": "I50.22",
  "code_display": "Chronic systolic heart failure",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The codes in category I13, Hypertensive heart and chronic kidney disease, are combination codes that include hypertension, heart disease and chronic kidney disease. Assign codes from combination category I13, Hypertensive heart and chronic kidney disease, when there is hypertension with both heart and chronic kidney disease. If heart failure is present, assign an additional code from category I50 to identify the type of heart failure.",
      "source": "CMS FY2027 ICD-10-CM Official Guidelines"
    }
  ],
  "rationale": "The chart documents 'Heart failure with reduced ejection fraction – EF 35% on last echo,' confirming systolic heart failure. However, the note does not explicitly state chronicity (chronic, acute, or acute on chronic). The code I50.22 specifically requires chronic systolic heart failure. While elevated BNP (580) and symptoms (dyspnea, orthopnea) are consistent with chronic HF, the acuity specifier is not directly documented. Per ICD-10-CM guidelines, specificity upgrades need chart evidence for the specific subcategory. Physician clarification is needed to confirm chronic versus acute systolic heart failure.",
  "physician_query_needed": true
}
